"""Render final fixed findings; no fitting, allocation changes, or extra replay."""
from common import *
import csv
def main():
 s=json.loads((OUT/'SELECTION_ANALYSIS.json').read_text());a=json.loads((OUT/'INDEPENDENT_AUDIT.json').read_text());can=json.loads((OUT/'CANARY_RESULTS.json').read_text());assert a['mismatch_N']==0 and can['failed_N']==0
 mainr=s['main'];control=s['control_read_only'];e=mainr['economic'];c=control['economic'];q=mainr['quality'];cq=control['quality'];cap=mainr['capture'];cc=control['capture'];head=json.loads((OUT/'HEAD_DIAGNOSTICS.json').read_text());pava=json.loads((OUT/'SCORE_FREEZE.json').read_text())
 def pct(v):return f'{v*100:.4f}%' if v is not None else 'NA'
 def yen(v):return f'¥{v:,.0f}' if v is not None else 'NA'
 def capture(x,k):r=x[k];return f"{r['funded_N']}/{r['total_N']} = {pct(r['capture_rate'])}"
 lines=['# Capital v4 MAX3 Upward Staircase Result','',f"作成: {now()}",'',f"1日幾何平均: **{pct(e['geometric_mean_daily_return'])}**",f"100万円→20日中央値: **{yen(e['rolling20_median']*1000000)}**",f"100万円→20日最大: **{yen(e['rolling20_maximum']*1000000)}**",f"200万円: **{'YES' if s['NORTH_STAR_HIT'] else 'NO'}**（rolling20 {e['north_star_hit_N']}/{e['valid_rolling20_window_N']}）",f"Medium capture: **{capture(cap,'Medium')}**",f"BigWinner5 capture: **{capture(cap,'U5')}**",f"MegaWinner10 capture: **{capture(cap,'U10')}**",f"<2% contamination: **{pct(q['below2_rate'])}**",f"Loser rate: **{pct(q['loss0_rate'])}**",'',f"選別判定: **{s['selection_status']}**。経済判定: **{s['economic_status']}**。North Starは独立判定。",'','## A. Control vs v4','', '| Metric | Control: CORE_P5 MAX3 Liquidity OFF | UPWARD_STAIRCASE_V4 MAX3 |','|---|---:|---:|']
 pairs=[('daily geometric',pct(c['geometric_mean_daily_return']),pct(e['geometric_mean_daily_return'])),('rolling20 median',f"{c['rolling20_median']:.8f}x",f"{e['rolling20_median']:.8f}x"),('rolling20 max',f"{c['rolling20_maximum']:.8f}x",f"{e['rolling20_maximum']:.8f}x"),('Final Equity',yen(c['final_equity']),yen(e['final_equity'])),('2x',f"{c['north_star_hit_N']}/{c['valid_rolling20_window_N']}",f"{e['north_star_hit_N']}/{e['valid_rolling20_window_N']}"),('MaxDD',pct(c['max_drawdown']),pct(e['max_drawdown'])),('utilization mean',pct(c['utilization_mean']),pct(e['utilization_mean'])),('funded N',cq['funded_N'],q['funded_N'])]
 pairs += [(k+' capture',capture(cc,k),capture(cap,k)) for k in ('U2','U3','Medium','U5','U10')]
 pairs += [(label,pct(cq[key]),pct(q[key])) for label,key in [('<2 contamination','below2_rate'),('<3 contamination','below3_rate'),('realized >=+1%','PF1_rate'),('realized >0%','positive_rate'),('realized =0%','exact_zero_rate'),('realized loser <=0%','loss0_rate'),('tail <=-1%','tail1_rate'),('tail <=-3%','tail3_rate'),('realized mean','realized_mean'),('realized median','realized_median'),('worst','worst'),('p05','p05')]]
 lines += [f'| {name} | {v1} | {v2} |' for name,v1,v2 in pairs]
 lines += ['', '| Success criterion | Result |','|---|---|']+[f'| {key} | {value} |' for key,value in s['scoreboard'].items()]
 upward=s['selection_status'];loser=s['scoreboard']['S5']=='PASS';pf=s['scoreboard']['S6']=='PASS'
 lines += ['',f"上方向の選別改善はS1/S2/S3で判定: {upward}。Loser抑制への波及はS5={s['scoreboard']['S5']}、利益+1%以上はS6={s['scoreboard']['S6']}として分けて評価する。",f"実測上、Loser率は{pct(cq['loss0_rate'])}→{pct(q['loss0_rate'])}、realized >=+1%率は{pct(cq['PF1_rate'])}→{pct(q['PF1_rate'])}。{'両指標への改善波及を観測。' if loser and pf else '両指標への改善波及は確認できなかった。'}単一のDevelopment比較で因果効果・将来収益は確立していない。",'','## B. Entry→High buckets','', '| Potential | candidate N | funded N | capture | realized mean | median | >=+1% | loser <=0% | tail <=-1% | actual PnL |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for label,b in mainr['buckets'].items():lines.append(f"| {label}% | {b['total_candidate_N']} | {b['funded_N']} | {pct(b['capture_rate'])} | {pct(b['realized_mean'])} | {pct(b['realized_median'])} | {pct(b['PF1_rate'])} | {pct(b['loss0_rate'])} | {pct(b['tail1_rate'])} | {yen(b['actual_pnl_jpy'])} |")
 lines += ['','## C. Milestone model / PAVA / ML','', '| Head | own-label OOF ROC AUC | Brier | observed base | top20 enrichment |','|---|---:|---:|---:|---:|']
 for h,d in head['heads'].items():lines.append(f"| {h} | {d['ROC_AUC']:.6f} | {d['Brier']:.6f} | {pct(d['observed_base_rate'])} | {d['top20_enrichment']:.6f}x |")
 lines += ['',f"PAVA raw violation: {pava['raw_violation_N']}/1039 ({pct(pava['raw_violation_rate'])}); projection mean L1={pava['projection_delta_L1_mean']:.8f}, max absolute={pava['projection_delta_max_abs']:.8f}。補正後monotonic違反0。",'PAVAはoutcomeを読まず、3確率の和を保存する。そのためMLのAdmissionと一次順位は和の補正前後で数学的に同じであり、補正は累積確率の整合性とtie-breakを担う。',f"ML cross-target AUC: {json.dumps(head['ML']['cross_target_AUC'],ensure_ascii=False)}",f"ML top20 (N={head['ML']['top20_N']}) milestone rates: {json.dumps(head['ML']['top20_rates'],ensure_ascii=False)}; <2 contamination {pct(head['ML']['top20_below2_contamination'])}。",'全decile observed rates、8 block AUC/base rates、H2/H3/H5 cross-target AUCはHEAD_DIAGNOSTICS.json。同cycle tuningへの利用0。','', '## D. Missed Winners / low-upside / slot regret','', '| Cohort | below baseline | MAX3 | cash/lot | cutoff | symbol open |','|---|---:|---:|---:|---:|---:|']
 for k,rs in mainr['missed_reasons'].items():lines.append(f"| {k} | {rs.get('UPWARD_BELOW_BASELINE',0)} | {rs.get('MAX_POSITION_CAP',0)} | {rs.get('CASH_OR_LOT_CONSTRAINED',0)} | {rs.get('CAPITAL_EOD_ENTRY_CUTOFF',0)} | {rs.get('SYMBOL_ALREADY_OPEN',0)} |")
 lines += ['', '同時刻batchのfuture-known評価。全missedとAdmission済みMAX3 rejectionのみを別集計し、各々batch/selected/missed/pair Nを示す。','', '| Slot regret | batch N | selected N | missed N | pair N |','|---|---:|---:|---:|---:|']
 for k,v in s['slot_regret'].items():
  if isinstance(v,dict) and 'pair_N' in v:lines.append(f"| {k} | {v['batch_N']} | {v['selected_N']} | {v['missed_N']} | {v['pair_N']} |")
 held=s['slot_regret']['HELD_SLOT_BLOCKED_WINNER'];lines += ['',f"MAX3によるmissed U5={s['slot_regret']['missed_U5_due_MAX3_N']}、U10={s['slot_regret']['missed_U10_due_MAX3_N']}。HELD_SLOT_BLOCKED_WINNER: U3={held['U3_N']}、U5={held['U5_N']}、U10={held['U10_N']}。",held['definition'],'future outcomeによるposition replacement0。Capital eligibility rejectとしてのLiquidity理由0。','', '## E. Thin liquidity diagnostic','', 'Hard reject OFF / position-size cap OFF。historical statusはeligibility・score・rank・quantityに使用0。','', '| Historical status | funded | U5 | U10 | mean | median | >=+1% | loser | no-trade MTM windows | PnL |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for k,v in mainr['liquidity_cohorts'].items():lines.append(f"| {k} | {v['funded_N']} | {v['U5_N']} | {v['U10_N']} | {pct(v['realized_mean'])} | {pct(v['realized_median'])} | {pct(v['PF1_rate'])} | {pct(v['loss0_rate'])} | {v['no_trade_MTM_windows_N']} | {yen(v['actual_pnl_jpy'])} |")
 old=mainr['old_reject52'];lines += ['',f"旧Liquidity reject52 cohort: funded {old['funded']['funded_N']}/52、actual PnL {yen(old['funded']['actual_pnl_jpy'])}。Missed理由 {json.dumps(old['missed_reasons'],ensure_ascii=False)}。",'各statusのtail、worst、p05、stale marks、Frozen/EOD fill内訳、旧52の全qualityはSELECTION_ANALYSIS.json。','', '## F. Economic daily / rolling20 / asset curve','',f"Daily geometric {pct(e['geometric_mean_daily_return'])}、arithmetic {pct(e['arithmetic_mean_daily_return'])}、median {pct(e['median_daily_return'])}。",f"rolling20 valid N={e['valid_rolling20_window_N']}、min={e['rolling20_minimum']:.8f}x、mean={e['rolling20_arithmetic_mean']:.8f}x、median={e['rolling20_median']:.8f}x、max={e['rolling20_maximum']:.8f}x、2x={e['north_star_hit_N']}/{e['valid_rolling20_window_N']}、earliest2x={e['earliest_2x_hit']}。",f"Final Equity {yen(e['final_equity'])}、total return {pct(e['total_return'])}、MaxDD {pct(e['max_drawdown'])}、utilization mean/median {pct(e['utilization_mean'])}/{pct(e['utilization_median'])}、time>=80/90% {pct(e['time_utilization_ge80'])}/{pct(e['time_utilization_ge90'])}。",f"minimum cash {yen(e['cash_minimum'])}、turnover {yen(e['turnover_cash_jpy'])}、recycled cash used {yen(e['capital_recycling_used_jpy'])}、funded/session {e['avg_funded_per_session']:.6f}。",f"session max-concurrent 0/1/2/3 counts: {json.dumps(e['session_max_concurrent_counts'])}。",f"paired daily delta: {json.dumps(s['paired_daily_delta'],ensure_ascii=False)}（return units、×100でpercentage points）。",'PAIRED_DAILY_RETURNS.csv、ROLLING20.csv、ASSET_CURVE_DAILY.csvを添付。minute-level actual mark/equity/cashはprivate CURVE.jsonl.gz。','', '## G. Integrity / Exposure / Safety','', f"H2 new fits8、H3 exact reuse8/new fit0、H5 exact reuse8/new fit0。HF1/HL0/H10/Movement fit/use0。Main MAX3 full replay1、Control replay0、MAX4/MAX5 0、S-only/A+/B+ rerun0。",f"Canary {can['canary_N']}/{can['canary_N']} PASS、independent checks {a['checks_N']}、mismatch={a['mismatch_N']}。Independent imports Primary=false。",'独立auditはscalar確率、4分割候補のisotonic projection、Fractionの配分/BUY/SELL/MTM/cash recycling、daily/rolling20、capture/contamination/realized qualityを再計算。共有IOの外部取得時点や取引所原本自体の真正性を新たに証明するauditではない。','決定性はscore再materialization、synthetic ledger再実行、独立実装による全38-session ledger一致で検証。追加のPrimary Development full replay0。',f"Exposure: **{EXPOSURE}**。この58 sessionsは既に複数Capital cycleの設計判断へ使用済み。rolling-origin予測であってもfresh/OOS性能ではなく、研究反復によるoverfit riskがある。North Star hitの有無に関わらずproductionReady=false。",'Protected/Holdout/Fresh/Validation/OOS/Prospective開封0、new provider requests0、Claude0、retune0、orders0、main merge0、force push0。Frozen Entry/EXIT変更0、Re-entry使用0、EXIT v4 rejected維持。',f"Safety: {json.dumps(SAFETY,ensure_ascii=False)}。",'既存teacherのstrictly-later actual High支援なし54件（うちpre-cutoff32件）は保存済みPotential=0を継承。新しい補完/ラベル変更は行っていない。実Highを持つ1546件の独立再計算差異0。この境界の原本定義は将来の別cycleで扱う必要があり、今回の結果の制約として残す。','', 'GitHub research branch: capital-state9-vnext-20261004。全checkpointのactual HEAD/tree/JSTはCHECKPOINT_INDEX.jsonとreceipts。','Main v4 1 run + audit + reportで結果を固定してSTOP。同cycleの閾値・weight・rank・MAX・Entry/EXIT変更0。次の判断はユーザーへ返す。']
 with (OUT/'REPORT-ja.md').open('x',encoding='utf-8') as f:f.write('\n\n'.join(lines)+'\n')
 daily=[]
 for m,co in zip(e['daily_series'],c['daily_series']):daily.append({'session':m['session'],'Control_equity_JPY':co['ending_cash'],'v4_equity_JPY':m['ending_cash'],'Control_daily_return':co['daily_return'],'v4_daily_return':m['daily_return']})
 with (OUT/'ASSET_CURVE_DAILY.csv').open('x',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(daily[0]));w.writeheader();w.writerows(daily)
 save(OUT/'NORTH_STAR_REPORT.json',{'JST':now(),'NORTH_STAR_HIT':s['NORTH_STAR_HIT'],'rolling20_N':e['valid_rolling20_window_N'],'hit_N':e['north_star_hit_N'],'hit_rate':e['north_star_hit_rate'],'earliest2x':e['earliest_2x_hit'],'amount_median_from_1m':e['rolling20_median']*1000000,'amount_max_from_1m':e['rolling20_maximum']*1000000,'selection_status':s['selection_status'],'economic_status':s['economic_status'],'Exposure':EXPOSURE,'productionReady':False,'Safety':SAFETY})
 checkpoint('U9_NORTH_STAR_REPORT','NORTH_STAR_AND_FINAL_REPORT_FIXED',{'NORTH_STAR_HIT':s['NORTH_STAR_HIT'],'selection_status':s['selection_status'],'economic_status':s['economic_status']},'Append closure and actual receipts, package immutable evidence, STOP.')
 print(json.dumps({'report':str(OUT/'REPORT-ja.md'),'NorthStar':s['NORTH_STAR_HIT']}),flush=True)
if __name__=='__main__':main()
